  json: {
    success: true,
    handoff_reason: parsed.handoff_reason || 'other',
    manager_summary: parsed.manager_summary || '',
    client_message: parsed.client_message || '',
    priority: parsed.priority || 'normal',
    next_action_recommendation: parsed.next_action_recommendation || '',
    lead_id: $('When Executed by Another Workflow').first().json.lead_id,
    workflow_name: 'Human_Handoff_Workflow',
    status: 'completed',
    recommended_next_step: 'wait_for_human',
    needs_human: true,
    timestamp: new Date().toISOString(),
  }
}];

